import os
from typing import Any, Dict, Optional

import requests


class OpenAIHostedModelInvoker:
    def __init__(
        self,
        api_key: Optional[str] = None,
        base_url: str = "https://api.openai.com/v1",
        default_model: str = "gpt-4.1-mini",
    ) -> None:
        self.api_key = api_key or os.getenv("OPENAI_API_KEY")
        if not self.api_key:
            raise ValueError("OPENAI_API_KEY is required")
        self.base_url = base_url.rstrip("/")
        self.default_model = default_model

    def resolve_model(self, model_name: Optional[str] = None) -> Dict[str, Any]:
        model = model_name or self.default_model
        resp = requests.get(
            f"{self.base_url}/models/{model}",
            headers={"Authorization": f"Bearer {self.api_key}"},
            timeout=30,
        )
        resp.raise_for_status()
        return resp.json()

    def invoke(
        self,
        prompt: str,
        model_name: Optional[str] = None,
        max_output_tokens: int = 256,
        temperature: float = 0.2,
    ) -> str:
        model_info = self.resolve_model(model_name)
        resolved_model = model_info["id"]

        payload = {
            "model": resolved_model,
            "input": prompt,
            "max_output_tokens": max_output_tokens,
            "temperature": temperature,
        }

        resp = requests.post(
            f"{self.base_url}/responses",
            headers={
                "Authorization": f"Bearer {self.api_key}",
                "Content-Type": "application/json",
            },
            json=payload,
            timeout=60,
        )
        resp.raise_for_status()
        data = resp.json()

        output_text = data.get("output_text")
        if output_text:
            return output_text

        chunks = []
        for item in data.get("output", []):
            for content in item.get("content", []):
                text = content.get("text")
                if text:
                    chunks.append(text)
        return "".join(chunks)


def resolve_and_invoke(prompt: str, model_name: Optional[str] = None) -> str:
    invoker = OpenAIHostedModelInvoker()
    return invoker.invoke(prompt=prompt, model_name=model_name)
